35: static void BreathAlgo_OnValley(uint32_t now)
36: {
37:     static uint32_t last_tick = 0;
38:     float interval_ms;
39:     float cbpm;
40:     float avg;
41:     float a;
42: 
43:     if (last_tick == 0) { last_tick = now; return; }
44:     interval_ms = (float)(now - last_tick);
45:     last_tick = now;
46:     if (interval_ms < 60000.0f/RR_MAX_BPM || interval_ms > 60000.0f/RR_MIN_BPM)
47:         return;
48:     
49:     cbpm = 60000.0f / interval_ms;
50:     s_cbpm[s_cbpm_cnt++ % 3] = cbpm;
51:     s_cbpm_total++;
52:     if (s_cbpm_total < 3) return;
53:     
54:     avg = (s_cbpm[0] + s_cbpm[1] + s_cbpm[2]) / 3.0f;
55:     if (s_cbpm_total == 3) {
56:         s_gbpm = floorf(avg + 0.5f);
57:         if (s_gbpm < RR_MIN_BPM) s_gbpm = RR_MIN_BPM;
58:         if (s_gbpm > 30.0f)      s_gbpm = 30.0f;
59:         g_guide_bpm = s_gbpm;
60:         s_initial_done = 1;
61:         return;
62:     }
63:     if ((s_cbpm_total % 3) == 0 && avg <= s_gbpm) {
64:         a = (s_gbpm > 10.0f) ? 2.0f : 1.0f;
65:         s_gbpm -= a;
66:         if (s_gbpm < RR_MIN_BPM) s_gbpm = RR_MIN_BPM;
67:         g_guide_bpm = s_gbpm;
68:     }
69: }
