32: /**
33:   * @brief  This function configures the TIM6 as a time base source.
34:   *         The time source is configured  to have 1ms time base with a dedicated
35:   *         Tick interrupt priority.
36:   * @note   This function is called  automatically at the beginning of program after
37:   *         reset by HAL_Init() or at any time when clock is configured, by HAL_RCC_ClockConfig().
38:   * @param  TickPriority: Tick interrupt priority.
39:   * @retval HAL status
40:   */
41: HAL_StatusTypeDef HAL_InitTick(uint32_t TickPriority)
42: {
43:   RCC_ClkInitTypeDef    clkconfig;
44:   uint32_t              uwTimclock, uwAPB1Prescaler = 0U;
45: 
46:   uint32_t              uwPrescalerValue = 0U;
47:   uint32_t              pFLatency;
48: 
49:   HAL_StatusTypeDef     status;
50: 
51:   /* Enable TIM6 clock */
52:   __HAL_RCC_TIM6_CLK_ENABLE();
53: 
54:   /* Get clock configuration */
55:   HAL_RCC_GetClockConfig(&clkconfig, &pFLatency);
56: 
57:   /* Get APB1 prescaler */
58:   uwAPB1Prescaler = clkconfig.APB1CLKDivider;
59:   /* Compute TIM6 clock */
60:   if (uwAPB1Prescaler == RCC_HCLK_DIV1)
61:   {
62:     uwTimclock = HAL_RCC_GetPCLK1Freq();
63:   }
64:   else
65:   {
66:     uwTimclock = 2UL * HAL_RCC_GetPCLK1Freq();
67:   }
68: 
69:   /* Compute the prescaler value to have TIM6 counter clock equal to 1MHz */
70:   uwPrescalerValue = (uint32_t) ((uwTimclock / 1000000U) - 1U);
71: 
72:   /* Initialize TIM6 */
73:   htim6.Instance = TIM6;
74: 
75:   /* Initialize TIMx peripheral as follow:
76:    * Period = [(TIM6CLK/1000) - 1]. to have a (1/1000) s time base.
77:    * Prescaler = (uwTimclock/1000000 - 1) to have a 1MHz counter clock.
78:    * ClockDivision = 0
79:    * Counter direction = Up
80:    */
81:   htim6.Init.Period = (1000000U / 1000U) - 1U;
82:   htim6.Init.Prescaler = uwPrescalerValue;
83:   htim6.Init.ClockDivision = 0;
84:   htim6.Init.CounterMode = TIM_COUNTERMODE_UP;
85:   htim6.Init.AutoReloadPreload = TIM_AUTORELOAD_PRELOAD_DISABLE;
86: 
87:   status = HAL_TIM_Base_Init(&htim6);
88:   if (status == HAL_OK)
89:   {
90:     /* Start the TIM time Base generation in interrupt mode */
91:     status = HAL_TIM_Base_Start_IT(&htim6);
92:     if (status == HAL_OK)
93:     {
94:     /* Enable the TIM6 global Interrupt */
95:         HAL_NVIC_EnableIRQ(TIM6_DAC_IRQn);
96:       /* Configure the SysTick IRQ priority */
97:       if (TickPriority < (1UL << __NVIC_PRIO_BITS))
98:       {
99:         /* Configure the TIM IRQ priority */
100:         HAL_NVIC_SetPriority(TIM6_DAC_IRQn, TickPriority, 0U);
101:         uwTickPrio = TickPriority;
102:       }
103:       else
104:       {
105:         status = HAL_ERROR;
106:       }
107:     }
108:   }
109: 
110:  /* Return function status */
111:   return status;
112: }
