void App_Therapy_OnScreenEvent(const ScreenEvent_t *evt)
{
    if (evt == NULL) return;

    if (evt->type == SCREEN_EVT_TOUCH && evt->touch_state == 0x00U)
    {
        switch (evt->comp_id)
        {
            case 1U: /* Breath Training Mode */
                g_app.Stim_Mode = STIM_MODE_OFF;
                g_app.sys_state = APP_STATE_SELECT_BREATH;
                BSP_Audio_PlayVoice(AUDIO_VOICE_SEL_BREATH_MODE);
                break;

            case 2U: /* Electrical Stimulation Mode */
                g_app.Breath_Mode = BREATH_MODE_OFF;
                g_app.sys_state = APP_STATE_SELECT_STIM;
                BSP_Audio_PlayVoice(AUDIO_VOICE_SEL_STIM_MODE);
                break;

            case 3U: /* Combined Mode */
                g_app.sys_state = APP_STATE_SELECT_BREATH;
                BSP_Audio_PlayVoice(AUDIO_VOICE_SEL_BREATH_MODE);
                break;

            case 4U: App_Therapy_SelectBreathMode(BREATH_MODE_SIMPLE); break;
            case 5U: App_Therapy_SelectBreathMode(BREATH_MODE_BIOFEEDBACK); break;
            case 6U: App_Therapy_SelectStimMode(STIM_MODE_CONTINUOUS); break;
            case 7U: App_Therapy_SelectStimMode(STIM_MODE_INTERMITTENT); break;
            case 8U: App_Therapy_SelectStimMode(STIM_MODE_DENSE_DISPERSE); break;
            case 10U: App_Therapy_StartOrPause(); break;
            case 11U: App_Therapy_StopToMenu(); break;
            case 12U:
                if (g_app.sys_state != APP_STATE_RUNNING)
                {
                    g_app.sys_state = APP_STATE_SETTINGS;
                    BSP_Screen_SetSettingsDisplay(g_app.volume, g_app.timer_min, g_app.ble_enabled);
                }
                break;
            default:
                break;
        }
    }
    else if (evt->type == SCREEN_EVT_CUSTOM_CMD && evt->payload_len >= 1U)
    {
        /* 0xAA <cmd_id> <value> ... FF FF FF */
        uint8_t val = evt->payload[0];
        switch (evt->cmd_id)
        {
            case 0x01U: /* Volume 0..10 */
                g_app.volume = (val > APP_VOL_MAX) ? APP_VOL_MAX : val;
                BSP_Audio_SetVolume(g_app.volume);
                break;
            case 0x02U: /* Timer 5..30 min */
                if (val < APP_TIMER_MIN_MIN) val = APP_TIMER_MIN_MIN;
                if (val > APP_TIMER_MIN_MAX) val = APP_TIMER_MIN_MAX;
                g_app.timer_min = val;
                break;
            case 0x03U: /* BLE toggle */
                g_app.ble_enabled = val ? 1U : 0U;
                BSP_BLE_SetEnabled(g_app.ble_enabled);
                break;
            case 0x04U: /* Stim freq 0..100 Hz */
                g_app.stim_freq_hz = (val > STIM_FREQ_MAX_HZ) ? STIM_FREQ_MAX_HZ : val;
                if (g_app.Stim_Mode == STIM_MODE_DENSE_DISPERSE && g_app.stim_freq_hz > 20U)
                {
                    g_app.stim_freq_hz = 20U;
                }
                BSP_Stim_SetBaseFreqHz(g_app.stim_freq_hz ? g_app.stim_freq_hz : 1U);
                break;
            case 0x05U: /* Channel level: payload[0]=ch(0..2), payload[1]=level(0..10) */
                if (evt->payload_len >= 2U && evt->payload[0] < 3U)
                {
                    uint8_t lvl = (evt->payload[1] > STIM_LEVEL_MAX) ? STIM_LEVEL_MAX : evt->payload[1];
                    g_app.stim_level[evt->payload[0]] = lvl;
                    BSP_Stim_SetChannelLevel(evt->payload[0], lvl);
                }
                break;
            default:
                break;
        }
    }
}

