243: /**
244:  * @brief  串口屏 FreeRTOS 任务入口函数（周期 20 ms）
245:  * @note   1. 持续从环形缓冲区提取完整帧并进入三级 switch-case 分发
246:  *         2. 治疗运行期按需节流刷新肺部动画（0~100）与剩余倒计时
247:  *         3. 每 10 秒刷新一次电池电量图标
248:  * @param  argument: FreeRTOS 任务参数（未使用）
249:  * @retval 无
250:  */
251: void ScreenTask(void const *argument)
252: {
253:     ScreenFrame_t frame;
254:     uint32_t tick_cnt = 0U;
255:     uint8_t  last_lung = 255U;      /* 上次已发送的肺部进度，用于变化检测节流 */
256:     uint16_t last_remain_s = 0xFFFFU;
257:     (void)argument;
258: 
259:     osDelay(50U);
260: 
261:     for (;;)
262:     {
263:         /* 1. 排空并解析所有以 0xFF 0xFF 0xFF 结尾的完整上行数据帧 */
264:         while (BSP_Screen_ReadFrame(&frame))
265:         {
266:             switch (frame.header)
267:             {
268:                 case SCREEN_FRAME_HDR_CTRL: /* 自定义协议帧：0x05 [page] [control] [value] */
269:                     if (frame.len >= 4U)
270:                     {
271:                         Screen_HandleCtrlFrame(frame.page, frame.control, frame.value);
272:                     }
273:                     break;
274: 
275:                 case SCREEN_FRAME_HDR_TOUCH: /* 淘晶驰原生触摸帧：0x65 [page] [comp] [event] */
276:                     if (frame.len >= 4U)
277:                     {
278:                         Screen_HandleTouchFrame(frame.page, frame.control, frame.value);
279:                     }
280:                     break;
281: 
282:                 default:
283:                     break;
284:             }
285:         }
286: 
287:         /* 2. 治疗运行中定时刷新肺部动画与剩余时间（值变化时才发送，降低串口负载） */
288:         if (g_app.running && !g_app.paused)
289:         {
290:             if (g_app.Breath_Mode != BREATH_MODE_OFF && g_app.lung_pct != last_lung)
291:             {
292:                 last_lung = g_app.lung_pct;
293:                 BSP_Screen_SetLungFill(last_lung);
294:             }
295: 
296:             if ((tick_cnt % 10U) == 0U) /* 每 200 ms 检查一次倒计时秒数变化 */
297:             {
298:                 uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
299:                 uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
300:                 uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
301:                 if (rem_s != last_remain_s)
302:                 {
303:                     last_remain_s = rem_s;
304:                     BSP_Screen_SetRemainTimeSec(rem_s);
305:                 }
306:             }
307:         }
308:         else
309:         {
310:             last_lung = 255U;
311:             last_remain_s = 0xFFFFU;
312:         }
313: 
314:         /* 3. 每 10 s（500 * 20 ms）刷新一次电量显示 */
315:         if ((tick_cnt % 500U) == 0U)
316:         {
317:             BSP_Screen_SetBattery(BSP_Power_GetBatteryPercent());
318:         }
319: 
320:         tick_cnt++;
321:         osDelay(20U);
322:     }
323: }

