7: #include "bsp_screen.h"
8: #include "usart.h"
9: #include "cmsis_os.h"
10: #include <stdio.h>
11: #include <string.h>
12: 
13: #define SCREEN_RX_RING_SIZE     256U    /**< 接收环形缓冲区容量（字节） */
14: 
15: /* SPSC（单生产者-单消费者）无锁环形缓冲区：
16:  * - 生产者：USART3 接收中断仅修改 s_rx_head
17:  * - 消费者：ScreenTask 任务仅修改 s_rx_tail
18:  * 因双方只各自更新自己的游标，无需关全局中断即可安全读写
19:  */
20: static uint8_t           s_rx_ring[SCREEN_RX_RING_SIZE];
21: static volatile uint16_t s_rx_head = 0U;            /**< 写游标（ISR 更新） */
22: static volatile uint16_t s_rx_tail = 0U;            /**< 读游标（Task 更新） */
23: static volatile uint32_t s_rx_overflow_cnt = 0U;    /**< 缓冲区满导致的丢字节计数 */
24: static uint8_t           s_rx_byte_it = 0U;         /**< HAL 单字节中断接收缓存 */
25: 
26: /* 任务层组帧缓冲区（仅在 ScreenTask 中访问） */
27: static uint8_t  s_frame_buf[SCREEN_FRAME_MAX_DATA];
28: static uint8_t  s_frame_len = 0U;                   /**< 当前已累计的字节长度 */
29: static uint8_t  s_ff_cnt    = 0U;                   /**< 连续收到的 0xFF 计数 */
30: 
31: static osMutexId s_tx_mutex = NULL;                 /**< 串口发送互斥锁（防止多任务指令混杂） */
32: 
33: /**
34:  * @brief  底层串口字节流发送函数（自动加锁保护多任务并发访问）
35:  * @param  data: 待发送数据缓冲区指针
36:  * @param  len: 发送字节数
37:  * @retval 无
38:  */
39: static void screen_uart_send_bytes(const uint8_t *data, uint16_t len)
40: {
41:     uint8_t locked = 0U;
42: 
43:     /* 仅在调度器已运行且不在中断上下文中时申请互斥锁 */
44:     if (s_tx_mutex != NULL && xTaskGetSchedulerState() == taskSCHEDULER_RUNNING && __get_IPSR() == 0U)
45:     {
46:         if (osMutexWait(s_tx_mutex, 50U) == osOK)
47:         {
48:             locked = 1U;
49:         }
50:     }
51: 
52:     HAL_UART_Transmit(&huart3, (uint8_t *)data, len, 50U);
53: 
54:     if (locked)
55:     {
56:         osMutexRelease(s_tx_mutex);
57:     }
58: }
59: 
60: /**
61:  * @brief  发送淘晶驰串口屏标准 3 字节结束符（0xFF 0xFF 0xFF）
62:  * @retval 无
63:  */
64: static void screen_send_end(void)
65: {
66:     static const uint8_t end[3] = {0xFFU, 0xFFU, 0xFFU};
67:     screen_uart_send_bytes(end, 3U);
68: }
