70: /**
71:  * @brief  初始化串口屏驱动（创建发送互斥锁，清空缓冲区并启动 USART3 单字节接收中断）
72:  * @retval 无
73:  */
74: void BSP_Screen_Init(void)
75: {
76:     if (s_tx_mutex == NULL)
77:     {
78:         osMutexDef(ScreenTxMtx);
79:         s_tx_mutex = osMutexCreate(osMutex(ScreenTxMtx));
80:     }
81: 
82:     s_rx_head = 0U;
83:     s_rx_tail = 0U;
84:     s_rx_overflow_cnt = 0U;
85:     s_frame_len = 0U;
86:     s_ff_cnt = 0U;
87: 
88:     /* 清除上电初期可能残留的过载错误标志，并使能首次单字节中断接收 */
89:     __HAL_UART_CLEAR_OREFLAG(&huart3);
90:     HAL_UART_Receive_IT(&huart3, &s_rx_byte_it, 1U);
91: }
92: 
93: /**
94:  * @brief  USART3 接收完成中断处理函数（在 HAL_UART_RxCpltCallback 中调用）
95:  * @note   中断内仅执行“入队 1 字节 + 立即重装接收中断”，确保中断响应时间极短
96:  * @retval 无
97:  */
98: void BSP_Screen_OnUartRxCplt(void)
99: {
100:     uint16_t next = (uint16_t)((s_rx_head + 1U) % SCREEN_RX_RING_SIZE);
101:     if (next != s_rx_tail)
102:     {
103:         s_rx_ring[s_rx_head] = s_rx_byte_it;
104:         s_rx_head = next;
105:     }
106:     else
107:     {
108:         /* 环形缓冲区已满：记录溢出次数，丢弃当前字节以保护未读取数据 */
109:         s_rx_overflow_cnt++;
110:     }
111: 
112:     /* 必须立即重新开启下一次单字节中断接收 */
113:     HAL_UART_Receive_IT(&huart3, &s_rx_byte_it, 1U);
114: }
115: 
116: /**
117:  * @brief  USART3 异常错误中断恢复函数（在 HAL_UART_ErrorCallback 中调用）
118:  * @note   热插拔屏幕或总线噪声可能触发 ORE（过载错误）并导致 HAL 停止接收，
119:  *         此处清除错误标志后重新启动单字节接收中断
120:  * @retval 无
121:  */
122: void BSP_Screen_OnUartError(void)
123: {
124:     __HAL_UART_CLEAR_OREFLAG(&huart3);
125:     __HAL_UART_CLEAR_FEFLAG(&huart3);
126:     __HAL_UART_CLEAR_NEFLAG(&huart3);
127:     HAL_UART_Receive_IT(&huart3, &s_rx_byte_it, 1U);
128: }
